#include <iostream>
using namespace std;

template <typename... Args>
int countAll(Args... args) {
    return sizeof...(args);
}

template <typename T, typename... Rest>
int firstAndRest(T first, Rest... rest) {
    return first * 10 + countAll(rest...);
}

int main() {
    cout << firstAndRest(3, 1, 2) << endl;
    cout << firstAndRest(7) << endl;
    return 0;
}

